CustomField.formula:
if(Weekday(DateValue(Adjusted_Touch_Date_Time_User__c)) = 1 || Weekday(DateValue(Adjusted_Touch_Date_Time_User__c)) = 7, "Weekend",
if(Touch_Time_Only_User__c < TimeValue("8:30:00.000"), "Before Work Hours", 
if(Touch_Time_Only_User__c > TimeValue("17:30:00.000"), "After Work Hours",
"Within Work Hours"
)))
